"""Generate the audit from measured artifacts, without invented completion percentages."""
import html,json
from pathlib import Path
root=Path(__file__).resolve().parents[1];docs=root/'docs';folder=docs/'visual-diff'
metrics=json.loads((folder/'actual/metrics.json').read_text())
checks=json.loads((folder/'browser-checks.json').read_text())
http=json.loads((docs/'test-results.json').read_text())
records=[]
for label in ['actual','desktop1440','mobile']:
 data=json.loads((folder/label/'capture.json').read_text());records.extend(data)
 assert len(data)==9 and all(not r['overflow'] and not r['php_error'] and not r['js_errors'] and r['layout_width']==r['width'] for r in data),label
assert all(r['passed'] for r in checks+http)
names={'index':'Dashboard Siswa','mata_pelajaran':'Mata Pelajaran Siswa','tugas':'Tugas Siswa','pengumuman':'Pengumuman Siswa','guru':'Dashboard Guru','guru_kelas':'Kelas Guru','guru_penilaian':'Penilaian Guru','guru_presensi':'Presensi Guru','login':'Login'}
notes={
'index':('Donut/grafik/kartu bertumpuk dan statistik kurang sesuai.','Layout chart dan statistik, tren nilai bulanan dari database, delta nilai dihitung, 3 mapel aktif dengan materi terbanyak, preview deskripsi tugas nyata. Fixture dashboard menghasilkan 14 mapel, 20 tugas, 18 dinilai, rata-rata 88.5, 12 mapel tuntas.','Waktu belajar mengikuti log nyata (fixture belum mereplikasi 12.5 jam). Beberapa isi tugas dan persen progress berbeda. Rasterisasi tulisan dan emoji salam berbeda dari PNG.'),
'mata_pelajaran':('Kartu kurang padat, ikon dan badge berbeda.','Enam kartu dari query relasi kelas, bukan array contoh; urutan mata pelajaran, badge tingkat XI, nama pengajar ringkas, glyph resmi calculate/auto_stories/science/terminal/translate/biotech. Jumlah materi/tugas fixture 12/3,10/1,14/2,16/4,8/2,11/1.','Teks, ketebalan raster font, baseline beberapa label, dan ikon metadata kecil masih memiliki selisih piksel.'),
 'tugas':('Daftar terlalu kosong, tinggi baris dan kolom judul berbeda.','Fixture khusus 5 tugas (4 menunggu, 1 nilai 90). Wrapping judul desktop mengikuti penyempitan kolom referensi, badge kategori ringkas, rosette verified, tile bahasa Inggris mint, metadata dan tombol tetap dinamis. Mobile memakai lebar judul normal.','Isi metadata/tanggal mengikuti waktu aplikasi. Tinggi tersisa +1 px dan raster font belum sama.'),
'pengumuman':('Kartu terlalu tinggi dan header/filter berbeda.','Spacing header/kartu dan preview, badge kategori, pencarian dan filter database, detail dalam dialog, pagination tetap berfungsi.','Penerbit, tanggal, isi preview serta jumlah total edaran belum sama dengan PNG. Ikon penerbit masih domain umum. Raster teks berbeda.'),
'guru':('Statistik, jadwal, panel bawah dan cover generik.','Statistik 5 kelas/178 siswa/24 berkas, presensi pekanan 96.4%, ringkasan kelas dipadatkan, jadwal terdekat tampil dari query, rail sesi, 3 jadwal dan 3 tugas serta pengumuman akademik.','Urutan/judul tugas, isi jadwal dan pengumuman berbeda. PNG menumpuk pengumuman menutupi sebagian tugas ketiga; aplikasi mempertahankan seluruh kontrol bisa diakses. Mode hybrid/QR tidak direkayasa karena belum tersimpan dalam model. Selisih tinggi terbaru tercantum pada tabel pengukuran.'),
'guru_kelas':('Foto kelas tidak sesuai dan kartu terlalu tinggi.','Lima foto cover asli dengan pemetaan subjek/kelas stabil, lima rombel unik, tabs tingkat kelas dengan track dari nama kelas, grid dan rail warna, 53 modul/10 tugas dari query.','Progress memakai rasio materi terbit terhadap seluruh materi; referensi memakai progress silabus/pertemuan. Belum ada model jurnal/silabus untuk menyamakan angka itu. Aksi yang belum didukung backend tidak dipalsukan.'),
'guru_penilaian':('Proporsi statistik, kartu, status dan panel bawah berbeda.','Empat status visual: ditutup mendesak, koreksi berjalan, masih terbuka, dan tuntas; rata-rata/nilai tertinggi/tanggal dinilai dari database. ZIP aman tetap berfungsi. Editor bobot panduan rubrik memvalidasi total 100 dan menyimpan preferensi lokal per guru.','Angka 106 dinilai/100% tepat waktu berbeda dari contoh 152/92%; tanggal, nilai tertinggi dan isi beberapa tugas berbeda. Rubrik merupakan panduan lokal dan tidak mengubah kalkulasi nilai. Tinggi +3 px; font belum identik raster.'),
'guru_presensi':('Komposisi tabel, jam, catatan dan rekap berbeda.','Statistik aktual 104/107 hadir dan 96.4% pekanan, enam baris per halaman, enam portrait asli, nama/NISN fixture cocok, label jam WIB, badge surat/olimpiade, kalender native berlabel Indonesia. Editor catatan/jam memperbarui field POST; simpan memakai backend dan CSRF existing.','Tanggal dan rekap bulan mengikuti waktu aplikasi; jumlah sesi bulanan/kategori catatan lain berbeda dari PNG. Raster font dan beberapa ikon kecil belum identik.'),
'login':('Logo, peran, proporsi panel dan jarak form berbeda.','Logo asli, kartu desktop 694 px, panel kiri 446 px, padding form dan spacing role/remember, glyph resmi peran/identitas/keamanan/token, tautan registrasi di footer.','Angka portal mengikuti database. SSO/token belum terhubung ke provider dan tidak dibuat seolah berfungsi. Teks ingat identitas sesuai perilaku aplikasi, bukan klaim sesi 30 hari. Font dan detail beberapa kontrol masih berbeda.')}
lines=['# Audit visual EduLMS - 15 Oktober 2026','','Target 100% belum terbukti. Status strict seluruh halaman: **BELUM SESUAI**. Tinggi sama bukan bukti identik piksel; MAE dan SSIM di bawah tidak dinyatakan sebagai persentase fidelity. Klaim lama 91% tidak dipakai.','','## Metode','','- Sembilan PNG asli di EduLMS_UI dibuka dengan tool gambar; Figma tidak dapat diinspeksi pada sesi ini. Tidak ada klaim memperoleh layer/vector Figma.',
'- Chrome Windows lokal, lebar 1280 CSS px, DSF 1, font Plus Jakarta Sans lokal. Scrollbar disembunyikan melalui CDP; setiap capture mencatat innerWidth dan clientWidth yang sama. Ini mengoreksi pengukuran lama yang dapat kehilangan 15 px akibat scrollbar.',
'- Bingkai dekoratif referensi dipotong: `(8,7,1288,height-8)`, login `(16,18,1296,1043)`. Koordinat dan region galat terbesar ada di metrics.json. Gambar tidak di-warp atau diskalakan untuk memperkecil galat.',
'- Capture 1280 memakai tinggi referensi dan full-page. Capture 1440/390 memeriksa responsivitas; tidak dianggap sebagai pembuktian identik untuk referensi 1280.',
'- MAE RGB 0-255: lebih kecil lebih dekat. SSIM adalah rerata blok lokal 8x8 tanpa overlap (implementasi visual_compare.py), bukan Gaussian skimage. Metrik mencakup konten teks/foto/data; tidak ada semantic mask tervalidasi. Irisan tinggi bersama dipakai untuk metrik, delta tinggi dilaporkan terpisah.',
'- Capture before/iteration/refinement disimpan sebagai jejak iterasi. State fixture dan metode scrollbar berkembang, sehingga perbandingan skor lintas iterasi bukan eksperimen desain dengan data identik.',
'- Percobaan font alternatif/variable dan text rendering disimpan di visual-diff/font-experiment; tidak diadopsi karena belum membuktikan kecocokan lebih baik. Rasterisasi tulisan Chrome ini terlihat berbeda dari PNG; perubahan font/CSS blur tidak dipakai untuk menyamarkan perbedaan.','','## Isolasi data','','Aplikasi tetap PHP/PDO dengan sesi, role, CSRF, query dan penyimpanan nyata. Tidak ada tabel UI yang diganti screenshot atau array contoh. Aset yang diambil dari referensi hanya fotografi/logo/portrait kecil.',
'Fixture screenshot khusus `edulms_qa_fidelity_reference_20261015` dibuat dari database QA visual sebelumnya, tidak dari produksi. `reference_fixture.php` hanya menerima nama database persis itu dan CLI. Setiap halaman disiapkan sebagai snapshot terpisah karena sembilan PNG memuat jumlah mapel, periode dan angka yang tidak konsisten antarhalaman. Snapshot tidak dipanggil oleh aplikasi produksi.',
'Tes transaksi memakai `edulms_qa_regression_20261015` pada port 8101. Fixture visual memakai port 8100. Pengujian mengunggah berkas QA di folder upload bersama, dengan akses tetap diperiksa backend.',
'Atas permintaan terbaru pengguna, database aplikasi kini berisi data dummy ringan: 10 murid baru, 6 guru existing, 260 materi, 90 tugas, 168 pengumpulan, 936 presensi, 12 pengumuman. Sebanyak 27 record asli diperiksa dan tetap sama; akun asli termasuk akun pengguna dipertahankan. Seed besar sebelumnya diganti hanya pada ID milik seeder, mengikuti instruksi pengguna. Seeder default kini 10 murid dan rerun menambahkan 0 record. Lihat [akun, perintah dan backup](DATA_DUMMY.md). Grafik membaca nilai dummy lima bulan melalui query biasa, bukan array pada view.','','## Pengukuran terakhir','','| Halaman | Tinggi referensi / aktual | Delta px | MAE RGB | SSIM lokal | Status strict |','|---|---:|---:|---:|---:|---|']
for r in metrics:
 lines.append(f"| {names[r['page']]} | {r['reference_size'][1]} / {r['actual_size'][1]} | {r['height_delta']:+d} | {r['mean_absolute_error_0_255']:.4f} | {r['local_ssim_8x8']:.5f} | BELUM SESUAI |")
lines+=['','## Rincian halaman','']
for r in metrics:
 n=r['page'];before,change,remaining=notes[n]
 lines += ['### '+names[n],'',f"Referensi: `EduLMS_UI/{r['reference']}`.",'',f'- Awal: {before}',f'- Diperbaiki: {change}',f'- Sisa: {remaining}',f'- Bukti: [aktual](visual-diff/actual/{n}.png), [referensi sejajar](visual-diff/actual/{n}-reference.png), [side-by-side](visual-diff/actual/{n}-side-by-side.png), [overlay](visual-diff/actual/{n}-overlay.png), [heatmap](visual-diff/actual/{n}-heatmap.png).','- Semua lebar diuji tanpa overflow halaman maupun error PHP/JS. Tabel presensi tetap bisa digeser horizontal pada layar kecil.','']
lines+=['## Validasi','',f'- {len(http)} tes HTTP lulus: autentikasi, role, CSRF, admin CRUD, penugasan, unggah/unduh, arsip ZIP, nilai, feedback, presensi dan ekspor.',f'- {len(checks)} tes browser lulus, termasuk editor jam/catatan presensi, validasi/persistensi bobot rubrik, filter tingkat kelas, pagination, modal, chart dan menu mobile.',
'- 61 file PHP lolos lint; seluruh Python docs lolos parsing AST.',f'- {len(records)} capture akhir (9 halaman x 3 lebar), semuanya clientWidth sesuai viewport dan bebas error/overflow. Bukti: capture.json pada actual, desktop1440, mobile.',
'- 296 kemunculan ikon/simbol di [audit ikon](ICON_FIDELITY_AUDIT.md); 75 glyph resmi Material Symbols Outlined disertakan dengan manifest sumber dan Apache LICENSE.','','## Reproduksi','','```powershell',"$env:EDULMS_DB_NAME='edulms_qa_fidelity_20261015'",'php docs/seed_visual_demo.php',"$env:EDULMS_DB_NAME='edulms_qa_fidelity_reference_20261015'",'php docs/reference_fixture.php login','php -S 127.0.0.1:8100 router.php','# Terminal lain: Chrome headless lokal, --remote-debugging-port=9223,','# --no-sandbox, --user-data-dir di .qa-tools/chrome-refinement.',
'python docs/visual_interactions.py --fixture','python docs/visual_capture.py --label actual --reference-height --fixture','python docs/visual_capture.py --label desktop1440 --width 1440 --fixture','python docs/visual_capture.py --label mobile --width 390 --fixture','python docs/visual_compare.py --label actual','python docs/build_visual_report.py','```','',
'Untuk tes HTTP jalankan server lain pada 8101 dengan EDULMS_DB_NAME=edulms_qa_regression_20261015, set EDULMS_QA_URL=http://127.0.0.1:8101 lalu python docs/test_e2e.py. Gunakan database QA terpisah.',
'','## Pekerjaan yang tersisa','','1. Samakan konten/metadata referensi dalam fixture bila sumber state tersedia; jangan hardcode hasil query produksi.',
'2. Pastikan keluarga/weight/font dan environment raster asli dari sumber desain; font alternatif belum terbukti lebih baik.',
'3. Model pertemuan silabus, mode sesi hybrid/QR dan provider SSO/token memerlukan fitur/data nyata sebelum tampilan dapat merepresentasikannya.',
'4. Iterasi detail wrapping, baseline dan spacing yang masih terlihat di overlay. Jangan menandai SELESAI atau 100% selama selisih penting masih ada.',
'5. Perubahan pengguna di working tree dipertahankan. Tidak ada commit, reset, atau deployment.','']
(docs/'UI_FIDELITY_REPORT.md').write_text('\n'.join(lines),encoding='utf-8')
progress=['# UI progress - 15 Oktober 2026','','**Target 100% belum tercapai.** Klaim lama 91% tidak digunakan sebagai bukti. Seluruh halaman masih BELUM SESUAI menurut definisi strict.','','Diperbarui: glyph Material Symbols resmi, snapshot QA per halaman, badge/mapel/tugas, tabel presensi dengan editor, rubrik editable sebagai panduan lokal, spacing login, chart dari database, rail dan statistik guru.','','| Halaman | Tinggi ref / aktual | Sisa |','|---|---:|---|']
for r in metrics:progress.append(f"| {names[r['page']]} | {r['reference_size'][1]} / {r['actual_size'][1]} | {notes[r['page']][2]} |")
progress+=['',f'{len(http)} tes HTTP, {len(checks)} tes browser, 61 lint PHP dan 27 capture akhir lulus. Data dummy ringan sudah diisi pada database aplikasi atas permintaan pengguna; fixture pembanding PNG tetap terpisah.','', '[Laporan dan batas pengukuran](UI_FIDELITY_REPORT.md) - [audit ikon](ICON_FIDELITY_AUDIT.md) - [galeri visual](visual-diff/index.html).','']
(docs/'UI_PROGRESS.md').write_text('\n'.join(progress),encoding='utf-8')
cards=[]
for r in metrics:
 n=r['page'];title=html.escape(names[n]);cards.append(f'<article><h2>{title}</h2><p>MAE {r["mean_absolute_error_0_255"]:.4f} &middot; SSIM blok {r["local_ssim_8x8"]:.5f} &middot; tinggi {r["reference_size"][1]} / {r["actual_size"][1]} px</p><div class="pair"><figure><img loading="lazy" src="actual/{n}-reference.png"><figcaption>Referensi sejajar</figcaption></figure><figure><img loading="lazy" src="actual/{n}.png"><figcaption>Aktual</figcaption></figure></div><p><a href="actual/{n}-side-by-side.png">Side-by-side</a> &middot; <a href="actual/{n}-overlay.png">Overlay 50%</a> &middot; <a href="actual/{n}-heatmap.png">Heatmap</a></p></article>')
gallery='<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>EduLMS visual audit</title><style>body{font:15px system-ui;background:#f7f8ff;color:#102239;max-width:1300px;margin:auto;padding:24px}article{background:white;padding:24px;border-radius:12px;margin:24px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}img{width:100%;border:1px solid #ddd}a{color:#006d66}figcaption{padding:8px}@media(max-width:700px){.pair{grid-template-columns:1fr}}</style><h1>EduLMS - audit visual 15 Oktober 2026</h1><p>Target strict belum tercapai. Konten dinamis termasuk metrik; skor bukan persentase fidelity. <a href="../UI_FIDELITY_REPORT.md">Laporan lengkap</a></p>'+''.join(cards)+'</html>'
(folder/'index.html').write_text(gallery,encoding='utf-8')
print('Reports and gallery generated from verified artifacts.')
